// Enable an entity; may be called multiple times. Parent must be enabled.
// Inputs provided by fuzzer: entity (valid handle)
// We treat any negative return as an error and bail.
{
  dds_return_t rc = dds_enable(*entity);
  if (rc < 0) { FUZZ_BAIL(); }
  // Track that this entity has been enabled to help other stubs enforce state
  FUZZ_SET_ATTR_INT(entity, "enabled", 1);
  // Validation: rc >= 0 means success or no-op; entity remains valid and is returned as output.
}
// Validation: Ensures negative errors bail; returns the input entity so it remains in the pool.

// Delete an entity; safe exactly once. Subsequent calls may return ALREADY_DELETED.
// Inputs: entity (valid or previously deleted handle)
{
  // If we know it's already deleted, allow calling but expect library to handle it.
  dds_return_t rc = dds_delete(*entity);
  if (rc < 0) {
    // Negative means an error other than OK; bail to avoid cascading invalid state
    FUZZ_BAIL();
  }
  // Mark entity as deleted so future stubs can avoid use-after-delete
  FUZZ_SET_ATTR_INT(entity, "deleted", 1);
}
// Validation: Does not return the entity, transferring no objects back to the pool.

// Get the mask of a ReadCondition or QueryCondition. mask must not be NULL.
{
  uint32_t mask = 0;
  dds_return_t rc = dds_get_mask(*condition, &mask);
  if (rc < 0) { FUZZ_BAIL(); }
  // Store mask as attribute for potential follow-up checks
  FUZZ_SET_ATTR_INT(condition, "cond_mask", (int)mask);
}
// Validation: Supplies non-null out param and preserves input condition.

// Retrieve instance handle for an entity; ihdl must not be NULL.
{
  dds_instance_handle_t ih = 0;
  dds_return_t rc = dds_get_instance_handle(*entity, &ih);
  if (rc < 0) { FUZZ_BAIL(); }
  FUZZ_SET_ATTR_INT(entity, "ih_valid", ih != 0);
}
// Validation: Uses a local out variable; keeps entity in pool.

